import Foundation

/// In-memory store for previews: nothing touches `UserDefaults`.
final class InMemoryFavoritesStore: FavoritesStore {
    private var movies: [Movie]

    init(movies: [Movie] = []) { self.movies = movies }

    func load() -> [Movie] { movies }
    func save(_ movies: [Movie]) { self.movies = movies }
}

/// Serves canned data. Never touches the network.
struct PreviewMovieService: MovieService {
    private static let movies: [Movie] = decode("""
    [
      {"id": 27205, "title": "Inception", "overview": "A thief enters dreams.",
       "release_date": "2010-07-15", "vote_average": 8.4, "vote_count": 35000, "genre_ids": [28, 878]},
      {"id": 496243, "title": "Parasite", "overview": "Two families collide.",
       "release_date": "2019-05-30", "vote_average": 8.5, "vote_count": 17000, "genre_ids": [35, 53]},
      {"id": 129, "title": "Spirited Away", "overview": "A girl enters a spirit world.",
       "release_date": "2001-07-20", "vote_average": 8.5, "vote_count": 16000, "genre_ids": [16]}
    ]
    """)

    private static let detail: MovieDetail = decode("""
    {"id": 27205, "title": "Inception", "overview": "A thief enters dreams.",
     "release_date": "2010-07-15", "vote_average": 8.4, "vote_count": 35000, "runtime": 148,
     "tagline": "Your mind is the scene of the crime.", "status": "Released",
     "genres": [{"id": 28, "name": "Action"}, {"id": 878, "name": "Science Fiction"}]}
    """)

    private static let credits: Credits = decode("""
    {"id": 27205,
     "cast": [{"id": 6193, "name": "Leonardo DiCaprio", "character": "Cobb", "order": 0}],
     "crew": [{"id": 525, "name": "Christopher Nolan", "job": "Director", "department": "Directing"}]}
    """)

    static var sampleMovies: [Movie] { movies }

    private static func decode<T: Decodable>(_ json: String) -> T {
        // Static literals: a failure here is a programmer error in this file.
        try! JSONDecoder.tmdb.decode(T.self, from: Data(json.utf8))
    }

    func popular(page: Int) async throws -> PagedResponse<Movie> {
        try Self.page(Self.movies)
    }

    func search(query: String, page: Int) async throws -> PagedResponse<Movie> {
        let needle = query.lowercased()
        return try Self.page(Self.movies.filter { $0.title.lowercased().contains(needle) })
    }

    func detail(id: Int) async throws -> MovieDetail { Self.detail }

    func credits(id: Int) async throws -> Credits { Self.credits }

    private static func page(_ results: [Movie]) throws -> PagedResponse<Movie> {
        let body = try JSONEncoder().encode(results)
        let json = #"{"page": 1, "total_pages": 1, "total_results": \#(results.count), "results": \#(String(decoding: body, as: UTF8.self))}"#
        return try JSONDecoder.tmdb.decode(PagedResponse<Movie>.self, from: Data(json.utf8))
    }
}
